```apex
/**
 * Opportunity domain class following the Apex Enterprise Patterns
 * (fflib-apex-common). All Opportunity business behaviour lives here; the
 * OpportunityTrigger contains no logic and only delegates to this class
 * through fflib_SObjectDomain.triggerHandler.
 *
 * Behaviour implemented here: when an Opportunity is created without a
 * CloseDate it defaults to today + 30 days; when it is created without a
 * Type it defaults to 'New Customer'. Values already provided by the caller
 * are never overwritten, and defaults are applied only on insert (never on
 * update), because this logic is wired exclusively to the before-insert hook.
 */
public inherited sharing class Opportunities extends fflib_SObjectDomain
{
    /**
     * Typed view of the wrapped records, taken from the list handed to the
     * constructor (the same list instance as Trigger.new in trigger context,
     * so field changes made here are persisted with the insert).
     */
    private final List<Opportunity> oppRecords;

    /**
     * Typed constructor, the usual entry point when the domain is built
     * directly from a typed list of Opportunity records.
     */
    public Opportunities(List<Opportunity> sObjectList)
    {
        super(sObjectList);
        oppRecords = sObjectList;
    }

    /**
     * Generic constructor used by the library when it constructs the domain
     * dynamically (fflib_SObjectDomain.triggerHandler / IConstructable path,
     * where the records arrive as a List<SObject>).
     */
    public Opportunities(List<SObject> sObjectList)
    {
        super(sObjectList);
        oppRecords = (List<Opportunity>) sObjectList;
    }

    /**
     * Standard inner class the library uses to construct this domain class
     * dynamically via fflib_SObjectDomain.triggerHandler.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities(sObjectList);
        }
    }

    /**
     * Before-insert hook dispatched by fflib_SObjectDomain.triggerHandler.
     * Because no equivalent hook is implemented for update, the defaults can
     * never be applied when records are updated.
     */
    public override void onBeforeInsert()
    {
        applyDefaults();
    }

    /**
     * Bulk-safe defaulting: one pass over all records, no SOQL/DML inside
     * the loop. Each field is defaulted independently and only when the
     * caller has not supplied a value.
     */
    @TestVisible
    private void applyDefaults()
    {
        Date defaultCloseDate = Date.today().addDays(30);

        for (Opportunity opp : oppRecords)
        {
            if (opp.CloseDate == null)
            {
                opp.CloseDate = defaultCloseDate;
            }
            if (opp.Type == null)
            {
                opp.Type = 'New Customer';
            }
        }
    }
}
