public inherited sharing class Opportunities extends fflib_SObjectDomain {

    private static final String STAGE_CLOSED_WON = 'Closed Won';

    public Opportunities(List<Opportunity> records) {
        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }

    public override void onValidate() {
        // Rule 1: on insert and on update, Amount must not be negative.
        validateAmountNotNegative();

        // Rule 2: on update, an opportunity whose stage was already Closed Won
        // before the update cannot have its Amount changed. Closing as won and
        // changing the amount in the same update is allowed (old stage not won yet).
        validateAmountUnchangedForWonOpportunities();
    }

    private void validateAmountNotNegative() {
        for (Opportunity record : (List<Opportunity>) Records) {
            if (record.Amount != null && record.Amount < 0) {
                error('Amount cannot be negative.', record, Opportunity.Amount);
            }
        }
    }

    private void validateAmountUnchangedForWonOpportunities() {
        // Only applicable in update context. Use the original (pre-update)
        // records; if none are available there is nothing to compare against.
        Map<Id, SObject> originalById = new Map<Id, SObject>(getOriginal());
        if (originalById.isEmpty()) {
            return;
        }

        for (Opportunity record : (List<Opportunity>) Records) {
            SObject original = originalById.get(record.Id);
            if (original == null) {
                continue;
            }

            String originalStage = (String) original.get(Opportunity.StageName);
            Decimal originalAmount = (Decimal) original.get(Opportunity.Amount);

            // Only enforce when the record was already Closed Won before the
            // update; closing as won in the same update is allowed.
            if (STAGE_CLOSED_WON.equals(originalStage)
                    && record.Amount != originalAmount) {
                error('Amount cannot change on a won opportunity.',
                        record, Opportunity.Amount);
            }
        }
    }
}
