public inherited sharing class OpportunityWinService {

    private static final String STAGE_CLOSED_WON = 'Closed Won';

    /**
     * Closes the given opportunities as 'Closed Won' (CloseDate = today) and, for each
     * opportunity that is actually saved, publishes one Deal_Won__e platform event for
     * Fulfilment.
     *
     * The opportunity updates and the event publication are registered on a single fflib
     * unit of work (from the Application.UnitOfWork factory) and committed once. Events
     * are registered with registerPublishAfterTransaction, so the unit of work publishes
     * them only after the opportunity updates have committed successfully: if saving
     * fails, commitWork() throws (and rolls back) before any event is published, no
     * Deal_Won__e goes out, and the exception propagates to the caller.
     *
     * Opportunities already at 'Closed Won' are skipped (and generate no event).
     *
     * @param opportunityIds the opportunities to close; null or empty is a no-op
     * @return the number of opportunities closed by this call
     */
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        List<SObject> opportunitiesToClose = new List<SObject>();
        List<SObject> dealWonEvents = new List<SObject>();

        for (Opportunity opportunity : opportunities) {
            // Already closed - this call did not close it, so Fulfilment must
            // not be notified about it again.
            if (opportunity.StageName == STAGE_CLOSED_WON) {
                continue;
            }

            opportunitiesToClose.add(new Opportunity(
                Id = opportunity.Id,
                StageName = STAGE_CLOSED_WON,
                CloseDate = Date.today()
            ));

            dealWonEvents.add(new Deal_Won__e(
                Opportunity_Id__c = opportunity.Id,
                Amount__c = opportunity.Amount
            ));
        }

        // Nothing to close (or everything was already Closed Won).
        if (opportunitiesToClose.isEmpty()) {
            return 0;
        }

        fflib_ISObjectUnitOfWork unitOfWork = Application.UnitOfWork.newInstance();
        unitOfWork.registerDirty(opportunitiesToClose);
        unitOfWork.registerPublishAfterTransaction(dealWonEvents);
        unitOfWork.commitWork();

        return opportunitiesToClose.size();
    }
}
