            String key = pairKey(ocr.OpportunityId, ocr.ContactId);
            OpportunityContactRole kept = roleByPairKey.get(key);
            if (kept == null) {
                roleByPairKey.put(key, ocr);
            } else {
                // Defensive: if a contact somehow has multiple roles on one opportunity,
                // prefer a role whose Role already equals the requested role.
                Map<Id, SoftCreditRequest> forOpp = byOppContact.get(ocr.OpportunityId);
                SoftCreditRequest req = forOpp != null ? forOpp.get(ocr.ContactId) : null;
                if (req != null && req.role != null && ocr.Role == req.role
