public inherited sharing class GiftService {

    private static final String ROLE_HOUSEHOLD_MEMBER = 'Household Member';
    private static final String ROLE_DONOR = 'Donor';
    private static final String STAGE_CLOSED_WON = 'Closed Won';

    public class GiftServiceException extends Exception {}

    /**
     * Records a gift that has already been received.
     *
     * Creates a Closed Won Opportunity on the contact's household Account,
     * sets the contact as the primary contact with a 'Donor' contact role,
     * gives every other household member a 'Household Member' role, and
     * creates exactly one paid NPSP Payment for the full amount dated giftDate.
     *
     * @param contactId the donor Contact Id
     * @param amount    the gift amount; must be a positive, non-null value
     * @param giftDate  the date the gift was received (used as CloseDate,
     *                  payment date and in the Opportunity Name)
     * @return the new Opportunity Id
     * @throws IllegalArgumentException if contactId is null/unknown or
     *         amount is null, zero or negative
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        // ---------- Input validation ----------
        if (contactId == null) {
            throw new IllegalArgumentException('Contact Id is required.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException(
                'Amount must be a positive, non-zero value.');
        }

        // ---------- Load donor (list query avoids NO_ROWS exception so we can
        // throw IllegalArgumentException instead) ----------
        List<Contact> donors = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (donors.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist: ' + contactId);
        }
        Contact donor = donors[0];

        Id householdAccountId = donor.AccountId;
        if (householdAccountId == null) {
            throw new IllegalArgumentException(
                'Contact does not belong to a household account.');
        }

        // ---------- Opportunity ----------
        String donorName = buildPersonName(donor.FirstName, donor.LastName);
        String dateStr = (giftDate != null) ? formatGiftDate(giftDate) : '';
        String oppName = donorName + ' Donation ' + dateStr;

        Opportunity opp = new Opportunity(
            Name = oppName,
            AccountId = householdAccountId,
            StageName = STAGE_CLOSED_WON,
            CloseDate = giftDate,
            npsp__Primary_Contact__c = contactId
        );
        insert opp;

        // ---------- Contact roles ----------
        // Other household members -> 'Household Member'; donor -> 'Donor' (primary).
        List<Contact> otherMembers = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :householdAccountId
              AND Id != :contactId
            ORDER BY Id
        ];

        List<OpportunityContactRole> rolesToInsert =
            new List<OpportunityContactRole>();
        Set<Id> contactsAlreadyOnOpp = new Set<Id>();

        for (Contact member : otherMembers) {
            if (contactsAlreadyOnOpp.contains(member.Id)) {
                continue; // never assign two roles to the same contact
            }
            rolesToInsert.add(new OpportunityContactRole(
                OpportunityId = opp.Id,
                ContactId = member.Id,
                Role = ROLE_HOUSEHOLD_MEMBER,
                IsPrimary = false
            ));
            contactsAlreadyOnOpp.add(member.Id);
        }

        // Donor's role is inserted last so the guard above would also catch it
        // if the donor somehow appeared in the household member query.
        rolesToInsert.add(new OpportunityContactRole(
            OpportunityId = opp.Id,
            ContactId = contactId,
            Role = ROLE_DONOR,
            IsPrimary = true
        ));
        insert rolesToInsert;

        // ---------- Payment ----------
        // Remove any payment NPSP auto-created so we end with exactly one.
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opp.Id
        ];
        if (!existingPayments.isEmpty()) {
            delete existingPayments;
        }

        npe01__OppPayment__c payment = new npe01__OppPayment__c(
            npe01__Opportunity__c = opp.Id,
            npe01__Payment_Amount__c = amount,
            npe01__Payment_Date__c = giftDate,
            npe01__Scheduled_Date__c = giftDate,
            npe01__Paid__c = true
        );
        insert payment;

        return opp.Id;
    }

    private static String buildPersonName(String firstName, String lastName) {
        String name = ((firstName != null) ? firstName : '') + ' ' +
                      ((lastName != null) ? lastName : '');
        return name.trim();
    }

    private static String formatGiftDate(Date d) {
        return d.year() + '-' +
            (d.month() < 10 ? '0' : '') + d.month() + '-' +
            (d.day() < 10 ? '0' : '') + d.day();
    }
}
