public without sharing class FamilyService {

    private static final String TYPE_PARENT = 'Parent';
    private static final String STATUS_CURRENT = 'Current';

    /**
     * For each child->parent pair, record in NPSP that the parent is the
     * child's "Parent" (status Current). NPSP's reciprocal relationship engine
     * (default List Setting method + the configured Parent lookup row: Male
     * Son / Female Daughter / Neutral Child) automatically creates the mirror
     * record naming the child as Son, Daughter or Child based on the child's
     * gender, so exactly one relationship record ends up in each direction.
     *
     * Idempotency: pairs where any relationship already exists between the two
     * contacts (in either direction) are skipped, so the import can be re-run
     * safely.
     *
     * Limits: at most 1 SOQL query and 1 DML statement per invocation,
     * regardless of pair count.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect all distinct contacts involved so a single SOQL query can
        // find any existing relationship between the pair members.
        Set<Id> contactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            if (childId != null) {
                contactIds.add(childId);
            }
            Id parentId = parentIdByChildId.get(childId);
            if (parentId != null) {
                contactIds.add(parentId);
            }
        }
        if (contactIds.isEmpty()) {
            return;
        }

        // Exactly 1 SOQL query: existing relationships among these contacts,
        // in both directions.
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
              AND npe4__RelatedContact__c IN :contactIds
        ]) {
            existingPairs.add(pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
        }

        // Build new relationships, skipping pairs that already have a
        // relationship in either direction, self-pairs, and duplicates within
        // the incoming map itself.
        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        Set<String> pendingKeys = new Set<String>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            String key = pairKey(childId, parentId);
            if (existingPairs.contains(key) || pendingKeys.contains(key)) {
                continue;
            }
            pendingKeys.add(key);

            // One record per pair, child -> parent with type "Parent". NPSP's
            // trigger creates the reciprocal record (Son/Daughter/Child), so
            // we must not insert the mirror record ourselves.
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = TYPE_PARENT,
                npe4__Status__c = STATUS_CURRENT
            ));
        }

        if (!toInsert.isEmpty()) {
            // Exactly 1 DML statement.
            insert toInsert;
        }
    }

    private static String pairKey(Id a, Id b) {
        String sa = String.valueOf(a);
        String sb = String.valueOf(b);
        return sa.compareTo(sb) < 0 ? sa + '-' + sb : sb + '-' + sa;
    }
}
