/**
 * TDTM Trigger Handler: OPP_MajorGiftFollowUp_TDTM
 *
 * NPSP Table-Driven Trigger Management (TDTM) handler for Opportunity
 * (AfterInsert / AfterUpdate).
 *
 * Behaviour:
 *   When an Opportunity qualifies as a major gift (Closed Won with Amount >= 5000),
 *   create one Task:
 *     Subject      = 'Major gift thank-you call'
 *     Priority     = 'High'
 *     Status       = 'Not Started'
 *     WhatId       = the Opportunity
 *     WhoId        = the Opportunity's npsp__Primary_Contact__c (may be null)
 *     OwnerId      = the Opportunity's OwnerId
 *     ActivityDate = the Opportunity's CloseDate + 3 days
 *
 *   On insert: create the Task when the Opportunity qualifies.
 *   On update: create the Task only when the Opportunity qualifies NOW and
 *              did NOT already qualify BEFORE (i.e. it was not already
 *              Closed Won with Amount >= 5000). Editing a gift that already
 *              qualified therefore never creates a second Task.
 *
 * The admin registers this class as an NPSP Trigger Handler record:
 *   Class = OPP_MajorGiftFollowUp_TDTM, Object = Opportunity,
 *   Trigger Action = AfterInsert;AfterUpdate, Load Order = 5, not asynchronous.
 *
 * No Apex trigger is needed: NPSP's TDTM dispatcher (npsp.TDTM_ObjectDataSink)
 * calls run() for every batch of Opportunities while the
 * npsp__Trigger_Handler__mdt record is active. When the admin deactivates that
 * record, NPSP's dispatcher stops routing records to this handler, so the
 * class stops running — no code change required.
 *
 * Bulk-safe: handles 200 Opportunities in one transaction using 0 SOQL
 * queries and 1 DML statement of its own (the records are already in memory
 * via the dispatcher's Trigger.new / Trigger.old lists, so no query is needed).
 */
public with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    /** Amount threshold for a "major gift". */
    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;

    /** Task field values. */
    private static final String TASK_SUBJECT  = 'Major gift thank-you call';
    private static final String TASK_PRIORITY = 'High';
    private static final String TASK_STATUS   = 'Not Started';
    private static final Integer DAYS_AFTER_CLOSE = 3;

    /**
     * NPSP TDTM entry point. Implements the abstract method declared on
     * npsp.TDTM_Runnable with the exact 4-parameter signature and the
     * npsp.TDTM_Runnable.DmlWrapper return type.
     *
     * Returns null when there is nothing to do; the dispatcher treats a null
     * return as "no DML". All Task inserts are performed here in a single
     * bulk DML statement.
     */
    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        List<Task> tasksToCreate = new List<Task>();

        for (Integer i = 0; i < newlist.size(); i++) {
            Opportunity newOpp = (Opportunity) newlist[i];
            if (newOpp == null) {
                continue;
            }

            Boolean qualifiesNow = isMajorGift(newOpp);
            Boolean shouldCreate = false;

            if (triggerAction == npsp.TDTM_Runnable.Action.afterInsert) {
                shouldCreate = qualifiesNow;
            } else if (triggerAction == npsp.TDTM_Runnable.Action.afterUpdate) {
                Opportunity oldOpp = (oldlist != null && oldlist.size() > i)
                    ? (Opportunity) oldlist[i]
                    : null;

                Boolean qualifiedBefore = oldOpp != null && isMajorGift(oldOpp);

                // "Updated so that it BECOMES Closed Won with Amount >= 5000
                //  when it was NOT both of those before."
                // Editing a gift that already qualified does not re-trigger.
                shouldCreate = qualifiesNow && !qualifiedBefore;
            }
            // Any other Action (afterDelete, beforeInsert, etc.) is not this
            // handler's concern; the dispatcher only routes the registered
            // Trigger Actions here anyway.

            if (shouldCreate) {
                tasksToCreate.add(buildTask(newOpp));
            }
        }

        // Single bulk DML statement for the whole batch.
        if (!tasksToCreate.isEmpty()) {
            insert tasksToCreate;
        }

        // Null return = no additional records for the dispatcher to DML.
        return null;
    }

    /** Core qualification: Closed Won with Amount >= 5000. */
    private Boolean isMajorGift(Opportunity opp) {
