```apex
public with sharing class RecordAccessService {

    // Max ids bound into one UserRecordAccess query. The governor limit
    // for items in an IN clause is 4000, so 2000 keeps headroom while
    // guaranteeing the documented input size of 2000 ids resolves in
    // exactly one SOQL query. Larger inputs are split across queries.
    private static final Integer QUERY_CHUNK_SIZE = 2000;

    // Safety cap on queries spent. 2000 ids at chunk size 2000 needs
    // exactly one query, well within the 20 query budget.
    private static final Integer MAX_SOQL_QUERIES = 20;

    // Returns the subset of recordIds that the running user can edit, as
    // reported by UserRecordAccess.HasEditAccess. This takes into account
    // object permissions, ownership, sharing rules, the role hierarchy,
    // View All, Modify All and Modify All Data, and reflects changes made
    // earlier in the same transaction.
    //
    // Records that do not exist or are not visible to the running user
    // yield no editable row and are excluded, which is the correct and
    // secure behavior for a mass edit screen.
    //
    // Null or empty input returns an empty set, never null. The caller's
    // input set is never mutated.
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> result = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return result;
        }

        // Drop null elements and work on a copy. Apex normalizes 15
        // character id forms to 18 characters on assignment, so plain set
        // semantics already handle 15 versus 18 character duplicates.
        Set<Id> sanitizedIds = new Set<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                sanitizedIds.add(recordId);
            }
        }

        if (sanitizedIds.isEmpty()) {
            return result;
        }

        // Query the platform access engine in chunks. For the contracted
        // 2000 ids this is exactly one SOQL query. UserId plus RecordId is
        // the required filter combination for UserRecordAccess.
        List<List<Id>> chunks = splitIntoChunks(sanitizedIds, QUERY_CHUNK_SIZE);
        Integer queriesUsed = 0;

        for (List<Id> chunk : chunks) {
            if (queriesUsed >= MAX_SOQL_QUERIES) {
                break;
            }
            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :UserInfo.getUserId()
                  AND RecordId IN :chunk
            ]) {
                // Check again in Apex for belt and braces. Only ids from
                // the input can appear here because of the IN filter.
                if (access.HasEditAccess) {
                    result.add(access.RecordId);
                }
            }
            queriesUsed++;
        }

        return result;
    }

    // Splits a set of ids into chunks of at most chunkSize elements each.
    // Returns a list of chunks, never null.
    private static List<List<Id>> splitIntoChunks(Set<Id> ids, Integer chunkSize) {
        List<List<Id>> chunks = new List<List<Id>>();
        List<Id> currentChunk = new List<Id>();

        for (Id recordId : ids) {
            currentChunk.add(recordId);
            if (currentChunk.size() >= chunkSize) {
                chunks.add(currentChunk);
                currentChunk = new List<Id>();
            }
        }
        if (!currentChunk.isEmpty()) {
            chunks.add(currentChunk);
        }
        return chunks;
    }
}
