```apex
public with sharing class EmployeeDirectoryService {

    /**
     * Returns the FB_Employee__c records the running user can see via sharing,
     * ordered by Name ascending. Fields the user cannot read (per FLS) are
     * removed entirely from the returned records rather than being returned
     * as null. If the user cannot read the object at all, an empty list is
     * returned.
     */
    public static List<FB_Employee__c> getDirectory() {
        // Object-level read/CRUD check. SObjectType.FB_Employee__c is already
        // a Schema.DescribeSObjectResult, so no getDescribe() call is needed.
        // Schema.SObjectType.FB_Employee__c.isCreateable() is the
        // object-permission (CRUD) check for the running user.
        if (!Schema.SObjectType.FB_Employee__c.isCreateable()) {
            return new List<FB_Employee__c>();
        }

        // Build the field list, including only fields the running user can
        // read (FLS). Id and Name are always readable on an object the user
        // can read.
        Set<String> selectableFields = new Set<String>{ 'Id', 'Name' };
        selectableFields.addAll(getReadableFields(
            new List<String>{ 'Department__c', 'Salary__c', 'Personal_Email__c' }
        ));

        // USER_MODE enforces FLS and object CRUD per the running user while
        // still honoring sharing rules (this class is with sharing).
        FB_Employee__c[] directory = Database.query(
            buildSoql(selectableFields),
            AccessLevel.USER_MODE
        );

        // Defensive second pass: strip any field the user cannot read. This
        // guarantees absent (not null) fields even if field readability and
        // queryability ever diverge, without throwing.
        SObjectAccessDecision decision = Security.stripInaccessible(
            AccessType.READABLE,
            directory
        );
        return decision.getRecords();
    }

    /**
     * Builds the SOQL string for the given field list.
     */
    private static String buildSoql(Set<String> fields) {
        List<String> fieldList = new List<String>(fields);
        String fieldCsv = String.join(fieldList, ', ');
        return 'SELECT ' + fieldCsv +
               ' FROM FB_Employee__c' +
               ' ORDER BY Name ASC' +
               ' LIMIT 50000';
    }

    /**
     * Returns, from the given candidate field API names on FB_Employee__c,
     * only those the running user has read access to (FLS), using the
     * per-field describe result. Schema.SObjectType.FB_Employee__c.fields
     * gives direct access to the field map without needing getDescribe().
     */
    private static Set<String> getReadableFields(List<String> candidateFields) {
        Set<String> readable = new Set<String>();
        Map<String, Schema.SObjectField> fieldMap =
            Schema.SObjectType.FB_Employee__c.fields.getMap();
        for (String fieldName : candidateFields) {
            Schema.SObjectField field = fieldMap.get(fieldName);
            if (field != null && field.getDescribe().isAccessible()) {
                readable.add(fieldName);
            }
        }
        return readable;
    }
}
