/**
 * Singleton query helper for Contact trigger actions.
 *
 * Loads the parent Accounts for the contacts in the trigger exactly once per
 * trigger execution and exposes them via getAccountsById() so multiple trigger
 * actions share the data without repeated SOQL queries.
 */
public with sharing class TA_Contact_Queries {

	private Map<Id, Account> accountsById;

	private static TA_Contact_Queries instance;

	private TA_Contact_Queries() {
		accountsById = new Map<Id, Account>();
	}

	public static TA_Contact_Queries getInstance() {
		if (instance == null) {
			instance = new TA_Contact_Queries();
		}
		return instance;
	}

	public Map<Id, Account> getAccountsById() {
		return accountsById;
	}

	/**
	 * Loads the Accounts referenced by the given contacts in a single query.
	 * Called by the Service trigger action at the start of every trigger
	 * execution; replaces any previously loaded data so later DML in the
	 * same transaction is always reflected.
	 */
	public void loadAccounts(List<Contact> contacts) {
		accountsById = new Map<Id, Account>();
		Set<Id> accountIds = new Set<Id>();
		for (Contact contact : contacts) {
			if (contact.AccountId != null) {
				accountIds.add(contact.AccountId);
			}
		}
		if (!accountIds.isEmpty()) {
			accountsById.putAll([
				SELECT Id,
					BillingStreet,
					BillingCity,
					BillingPostalCode,
					BillingCountry,
					AccountSource
				FROM Account
				WHERE Id IN :accountIds
			]);
		}
	}
}
