/**
 * Contact before-insert action: when a new contact has an Account and all four
 * mailing address fields are blank, inherit the account billing address.
 * Contacts with any mailing field filled in keep their own address; contacts
 * without an Account are left alone.
 *
 * Relies on TA_Contact_Queries_Service (Order__c = 1) having loaded the parent
 * accounts, so this action performs no SOQL of its own.
 */
public with sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {

	public void beforeInsert(List<SObject> triggerNew) {
		Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().getAccountsById();
		for (Contact contact : (List<Contact>) triggerNew) {
			if (contact.AccountId == null) {
				continue;
			}
			Boolean allBlank =
				contact.MailingStreet == null &&
				contact.MailingCity == null &&
				contact.MailingPostalCode == null &&
				contact.MailingCountry == null;
			if (!allBlank) {
				continue;
			}
			Account account = accountsById.get(contact.AccountId);
			if (account == null) {
				continue;
			}
			contact.MailingStreet = account.BillingStreet;
			contact.MailingCity = account.BillingCity;
			contact.MailingPostalCode = account.BillingPostalCode;
			contact.MailingCountry = account.BillingCountry;
		}
	}
}
